// =====================
// JS_OTP_Verify (Complete)
// Outputs EXACT 6 fields:
// - otp_attempts
// - otp_last_entered
// - otp_verified
// - otp_status
// - otp_code
// - otp_status_message
// =====================

const text = String($input || "").trim();

// --- Read current state ---
const otpStatusRaw = String($flow.state.otp_status || "").trim();
const otpStatus = otpStatusRaw.toLowerCase();

const otpCodeRaw = String($flow.state.otp_code || "").trim();           // correct OTP
const attempts0 = Number($flow.state.otp_attempts || 0);

// Expiry (epoch ms string). If missing/invalid -> treat as expired for safety.
const expiresAtRaw = String($flow.state.otp_expires_at || "").trim();
const expiresAtMs = expiresAtRaw ? Number(expiresAtRaw) : NaN;

// --- Defaults (keep current) ---
let otp_attempts = String($flow.state.otp_attempts || "0");
let otp_last_entered = "";
let otp_verified = String($flow.state.otp_verified || "").trim(); // keep existing if already verified
let otp_status = otpStatusRaw || "";
let otp_code = otpCodeRaw;
let otp_status_message = "";

// =====================
// 1) Must have active session: otp_status === "sent"
// =====================
if (otpStatus !== "sent") {
  return {
    otp_attempts: String(attempts0),
    otp_last_entered: "",
    otp_verified: otp_verified || "",
    otp_status: otp_status || "",
    otp_code: otp_code || "",
    otp_status_message:
      "There is no active OTP session right now. Please request a new OTP."
  };
}

// =====================
// 2) Expiry check (Option B explicit "expired")
// =====================
const nowMs = Date.now();
if (!Number.isFinite(expiresAtMs) || nowMs > expiresAtMs) {
  return {
    otp_attempts: "0",
    otp_last_entered: "",
    otp_verified: "",
    otp_status: "expired",
    otp_code: "",
    otp_status_message: "OTP has expired. Please request a new OTP."
  };
}

// =====================
// 3) Extract OTP digits from user text
// - 4 to 8 digits allowed (keeps your current robustness)
// =====================
const matches = text.match(/\b\d{4,8}\b/g) || [];

// No digits
if (matches.length === 0) {
  return {
    otp_attempts: String(attempts0),
    otp_last_entered: "",
    otp_verified: "",
    otp_status: "sent",
    otp_code: otpCodeRaw,
    otp_status_message: "Please type the OTP digits only."
  };
}

// Multiple codes => ambiguous (do not increment attempts)
if (matches.length > 1) {
  return {
    otp_attempts: String(attempts0),
    otp_last_entered: "",
    otp_verified: "",
    otp_status: "sent",
    otp_code: otpCodeRaw,
    otp_status_message:
      `I found multiple codes (${matches.join(", ")}). Please type ONLY your OTP digits.`
  };
}

// Single candidate
const candidate = matches[0];
otp_last_entered = candidate;

// Safety: missing otp_code in state (should not happen if generate step worked)
if (!otpCodeRaw) {
  return {
    otp_attempts: String(attempts0),
    otp_last_entered,
    otp_verified: "",
    otp_status: "expired", // treat as expired/broken session
    otp_code: "",
    otp_status_message:
      "OTP session error (missing OTP code). Please request a new OTP."
  };
}

// =====================
// 4) Compare
// =====================

// Correct OTP
if (candidate === otpCodeRaw) {
  return {
    otp_attempts: "0",
    otp_last_entered,
    otp_verified: "true",
    otp_status: "verified",
    otp_code: "", // clear after success
    otp_status_message: "OTP verified successfully. Please continue with your request."
  };
}

// Wrong OTP => increment attempts
const attemptsNew = attempts0 + 1;

// Locked
if (attemptsNew >= 3) {
  return {
    otp_attempts: String(attemptsNew),
    otp_last_entered,
    otp_verified: "",
    otp_status: "locked",
    otp_code: "", // optional clear on lock
    otp_status_message:
      "Incorrect OTP too many times. OTP verification is locked. Please request a new OTP."
  };
}

// Still can retry
return {
  otp_attempts: String(attemptsNew),
  otp_last_entered,
  otp_verified: "",
  otp_status: "sent",
  otp_code: otpCodeRaw,
  otp_status_message: `Incorrect OTP. Please try again. (Attempt ${attemptsNew}/3)`
};

