let payload = $httpResult;

// If it's a string, parse it
if (typeof payload === "string") {
  try {
    payload = JSON.parse(payload);
  } catch (e) {
    return {
      action_ok: false,
      error_code: "BAD_JSON",
      message_user: "System error: invalid response format."
    };
  }
}

// Some HTTP outputs are wrapped under { data: {...} }
const data = payload?.data ?? payload;

// Interpret
const success = (data.success === true || data.success === "true");
const opType = data.op_type ?? data.opType ?? null;
const caseId = data.case_id ?? data.caseId ?? null;

if (success) {
  return {
    action_ok: true,
    action: opType,
    case_id: caseId,
    message_user: `Ticket ${caseId} created successfully.`
  };
}

return {
  action_ok: false,
  error_code: data.error_code ?? data.errorCode ?? "UNKNOWN_ERROR",
  message_user: data.message ?? data.message_user ?? "Operation failed. Please try again."
