// JS_AllInOne_Draft3 v1
// Input: $raw (LLM output string), prev_* (flow state)
// Output: draft3_* fields (merged + normalized + email validation)

// ---------- Repair helpers ----------
function extractJsonBlock(s) {
  const str = String(s ?? "");
  const start = str.indexOf("{");
  const end = str.lastIndexOf("}");
  if (start === -1 || end === -1 || end <= start) return str.trim();
  return str.slice(start, end + 1).trim();
}

function repairJsonString(s) {
  let t = String(s ?? "");
  t = t.replace(/[“”]/g, '"').replace(/[‘’]/g, "'");
  t = t.replace(/^\uFEFF/, "");

  let out = "";
  let inStr = false;
  let esc = false;

  const nextNonSpace = (str, idx) => {
    for (let i = idx + 1; i < str.length; i++) {
      const c = str[i];
      if (c === " " || c === "\t" || c === "\r" || c === "\n") continue;
      return c;
    }
    return null;
  };

  for (let i = 0; i < t.length; i++) {
    const c = t[i];

    if (esc) { out += c; esc = false; continue; }
    if (c === "\\") { out += c; esc = true; continue; }

    if (c === '"') {
      if (!inStr) {
        inStr = true; out += '"';
      } else {
        const ahead = nextNonSpace(t, i);
        const isStringEnd = ahead === null || ahead === "," || ahead === "}" || ahead === "]" || ahead === ":";
        out += isStringEnd ? '"' : '\\"';
        if (isStringEnd) inStr = false;
      }
      continue;
    }

    if (inStr && (c === "\n" || c === "\r")) { out += "\\n"; continue; }
    out += c;
  }

  return out;
}

// ---------- Sanitize helpers ----------
function sanitizeString(v) {
  if (v === null || v === undefined) return "";
  let s = (typeof v === "string") ? v : String(v);
  s = s.replace(/\r\n/g, "\n").replace(/\r/g, "\n");
  s = s.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, "");
  return s.trim();
}

function sanitizeNullable(v) {
  if (v === null || v === undefined) return null;
  const s = sanitizeString(v);
  if (!s) return null;
  const low = s.toLowerCase();
  if (low === "null" || low === "undefined") return null;
  if (s.includes("{{") || s.includes("}}")) return null;
  return s;
}

function asArray(v) {
  if (Array.isArray(v)) return v;
  if (v === null || v === undefined) return [];
  if (typeof v === "string") {
    const s = v.trim();
    if (!s || s.includes("{{") || s.includes("}}")) return [];
    try {
      const parsed = JSON.parse(s);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }
  return [];
}

function normalizeErrorList(v) {
  if (Array.isArray(v)) return v.map(sanitizeString).filter(Boolean);
  const s = sanitizeString(v);
  if (!s || s === "[]" || s.toLowerCase() === "null" || s.toLowerCase() === "undefined") return [];
  return [s];
}

// ---------- 1) Parse current LLM output ----------
let cur = {
  success: false,
  case_id: null,
  engineer_email: null,
  changes: [],
  errors: "Invalid JSON-safe extraction"
};

try {
  const block = extractJsonBlock($raw);
  const repaired = repairJsonString(block);
  const obj = JSON.parse(repaired);

  cur = {
    success: obj.success === false ? false : true,
    case_id: obj.case_id ?? null,
    engineer_email: obj.engineer_email ?? null,
    changes: Array.isArray(obj.changes) ? obj.changes : [],
    errors: obj.errors ?? null
  };
} catch (e) {
  // keep fallback
}

// ---------- 2) Sanitize current ----------
cur.case_id = sanitizeNullable(cur.case_id);
cur.engineer_email = sanitizeNullable(cur.engineer_email);
cur.errors = sanitizeNullable(cur.errors);

const allowedFields = new Set(["site","pic","problem_title","action_description","start_date","end_date"]);

cur.changes = (Array.isArray(cur.changes) ? cur.changes : [])
  .filter(ch => ch && typeof ch === "object")
  .map(ch => {
    const field = sanitizeString(ch.field);
    const opRaw = sanitizeString(ch.op).toLowerCase();
    const op = (opRaw === "replace" || opRaw === "append" || opRaw === "remove") ? opRaw : "append";
    const value = sanitizeString(ch.value);
    return { field, op, value };
  })
  .filter(ch => allowedFields.has(ch.field));

// ---------- 3) Read prev sticky ----------
const prevCaseId = sanitizeNullable($prev_case_id);
const prevEmail  = sanitizeNullable($prev_engineer_email);
const prevChanges = asArray($prev_changes);
const prevErrors  = normalizeErrorList($prev_errors);

// ---------- 4) Sticky merge (case/email) ----------
const mergedCaseId = cur.case_id ?? prevCaseId;
const mergedEmail  = cur.engineer_email ?? prevEmail;

// Only merge changes if current success=true
const mergedRawChanges = (cur.success === true) ? [...prevChanges, ...cur.changes] : [...prevChanges];

// ---------- 5) Normalize changes (merge multiple appends per field) ----------
const bucket = new Map();

for (const ch of mergedRawChanges) {
  if (!ch || !ch.field) continue;
  const field = String(ch.field);
  const op = String(ch.op || "append").toLowerCase();
  const value = (ch.value === null || ch.value === undefined) ? "" : String(ch.value);

  if (!bucket.has(field)) bucket.set(field, { replace: null, appends: [], remove: false });

  const b = bucket.get(field);
  if (op === "replace") b.replace = value;
  else if (op === "remove") b.remove = true;
  else if (value.trim()) b.appends.push(value);
}

const normalizedChanges = [];
for (const [field, b] of bucket.entries()) {
  if (b.replace !== null) normalizedChanges.push({ field, op: "replace", value: b.replace });
  else if (b.remove) normalizedChanges.push({ field, op: "remove", value: "" });
  else if (b.appends.length) normalizedChanges.push({ field, op: "append", value: b.appends.join("\n") });
}

// ---------- 6) Email validation (fix your “missing vs invalid” issue) ----------
let draft3_email_valid = false;
let draft3_email_error = "";

const email = mergedEmail ? String(mergedEmail).trim() : "";

if (!email) {
  draft3_email_valid = false;
  draft3_email_error = "MISSING_ENGINEER_EMAIL";
} else {
  const basicRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!basicRe.test(email)) {
    draft3_email_valid = false;
    draft3_email_error = "INVALID_ENGINEER_EMAIL_FORMAT";
  } else {
    // OPTIONAL: your org rules (edit as you like)
    const allowedDomains = ["exactautomation.com.my", "sediateuguh.com.my"];
    const blockedEmails = ["engineer@example.com", "engineer@example.com"];
    const overrideAllow = ["engineer@example.com"];

    const low = email.toLowerCase();
    const domain = (low.split("@")[1] || "").toLowerCase();

    if (blockedEmails.includes(low)) {
      draft3_email_valid = false;
      draft3_email_error = "EMAIL_ADDRESS_NOT_ALLOWED";
    } else if (overrideAllow.includes(low)) {
      draft3_email_valid = true;
      draft3_email_error = "";
    } else if (!allowedDomains.includes(domain)) {
      draft3_email_valid = false;
      draft3_email_error = "EMAIL_DOMAIN_NOT_ALLOWED";
    } else {
      draft3_email_valid = true;
      draft3_email_error = "";
    }
  }
}

// ---------- 7) Errors behavior ----------
const mergedErrors = (cur.success === true) ? [] : normalizeErrorList(cur.errors).concat(prevErrors);

// ---------- 8) Flags for Checker3 / OTP ----------
const draft3_has_errors  = Array.isArray(mergedErrors) && mergedErrors.length > 0;
const draft3_has_case    = !!(mergedCaseId && String(mergedCaseId).includes("CASE-"));
const draft3_has_changes = Array.isArray(normalizedChanges) && normalizedChanges.length > 0;

const draft3_ready_for_otp =
  draft3_has_case &&
  draft3_has_changes &&
  (draft3_email_valid === true) &&
  !draft3_has_errors;

const draft3_ready_token = draft3_ready_for_otp ? "READY_FOR_OTP" : "";

// ---------- 9) Return (these can be written to flow state) ----------
return {
  draft3_case_id: mergedCaseId,
  draft3_engineer_email: mergedEmail,
  draft3_changes: normalizedChanges,
  draft3_errors: mergedErrors,
  draft3_success: cur.success,

  draft3_email_valid,
  draft3_email_error,
  draft3_ready_for_otp,
  draft3_ready_token,

  draft3_has_errors,
  draft3_has_case,
  draft3_has_changes
};

