// ---------- helpers: parse/repair ----------
function stripCodeFences(s) {
  if (typeof s !== 'string') return s;
  // remove ```json ... ``` or ``` ... ```
  return s.replace(/```(?:json)?\s*/gi, '').replace(/```/g, '').trim();
}

function extractFirstJsonObject(s) {
  // best-effort: find the first {...} block
  if (typeof s !== 'string') return null;
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  return s.slice(start, end + 1);
}

function safeParseJson(maybe) {
  if (maybe == null) return null;

  // If Flowise already passes an object, accept it.
  if (typeof maybe === 'object') return maybe;

  // Otherwise attempt to parse string.
  let s = String(maybe);
  s = stripCodeFences(s);

  // Try direct parse
  try {
    return JSON.parse(s);
  } catch (_) {
    // Try extracting first { ... }
    const candidate = extractFirstJsonObject(s);
    if (!candidate) return null;
    try {
      return JSON.parse(candidate);
    } catch (__) {
      return null;
    }
  }
}

// ---------- helpers: sanitize + sticky merge ----------
function normalizeString(v) {
  if (v == null) return null;
  if (typeof v !== 'string') v = String(v);
  const t = v.trim();
  if (!t) return null;
  // optional: remove weird zero-width spaces
  return t.replace(/[\u200B-\u200D\uFEFF]/g, '').trim();
}

function pickSticky(incoming, prev) {
  // incoming wins only if it's a real, non-empty value
  const n = normalizeString(incoming);
  if (n == null) return prev ?? '';
  return n;
}

// ---------- email validation (same logic as your JS_ValidateEmail) ----------
function validateEmail(engineerEmail) {
  const email = (engineerEmail || '').trim();

  const allowedDomains = [
    'exactautomation.com.my',
    'sediateguh.com.my'
  ];

  const specialAllowedEmails = [
    'engineer@example.com',
    'engineer@example.com'
  ].map(e => e.toLowerCase());

  const blockedEmails = [
    'engineer@example.com',
    'engineer@example.com',
    'engineer@example.com'
  ].map(e => e.toLowerCase());

  let valid = false;
  let reason = '';

  if (!email) {
    reason = 'empty';
  } else {
    const lowerEmail = email.toLowerCase();
    const match = lowerEmail.match(/^[^@\s]+@([^@\s]+)$/);

    if (!match) {
      reason = 'invalid_format';
    } else {
      const domain = match[1];

      if (blockedEmails.includes(lowerEmail)) {
        valid = false;
        reason = 'blocked_email';
      } else if (specialAllowedEmails.includes(lowerEmail)) {
        valid = true;
        reason = '';
      } else if (allowedDomains.includes(domain)) {
        valid = true;
        reason = '';
      } else {
        valid = false;
        reason = 'invalid_domain';
      }
    }
  }

  return { email, valid, reason };
}

