/**
 * JS_NormalizeValidateDates_Create
 *
 * Inputs:
 *  - $start_raw  (e.g. "yesterday", "12 Jan 2026", "12-01-2026", "2026-01-12")
 *  - $end_raw    (e.g. "OPEN", "today", "12-01-2026", "")
 *
 * Outputs:
 *  {
 *    start_date_norm: "YYYY-MM-DD" or "",
 *    end_date_norm:   "YYYY-MM-DD" or "OPEN" or "",
 *    date_valid: boolean,
 *    date_error: string
 *  }
 *
 * Malaysia assumption for ambiguous numeric dates: DD-MM-YYYY (common local style).
 */

function clean(s) {
  if (s == null) return "";
  return String(s).trim();
}

function pad2(n) {
  return String(n).padStart(2, "0");
}

function toMYDatePartsNow() {
  // best-effort MY date without timezone libs:
  // convert from UTC to +08:00
  const now = new Date();
  const utcMs = now.getTime() + (now.getTimezoneOffset() * 60000);
  const myMs = utcMs + (8 * 60 * 60000);
  const d = new Date(myMs);
  return { y: d.getUTCFullYear(), m: d.getUTCMonth() + 1, d: d.getUTCDate() };
}

function partsToISO(y, m, d) {
  return `${y}-${pad2(m)}-${pad2(d)}`;
}

function addDaysISO(iso, deltaDays) {
  const [y, m, d] = iso.split("-").map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  dt.setUTCDate(dt.getUTCDate() + deltaDays);
  return partsToISO(dt.getUTCFullYear(), dt.getUTCMonth() + 1, dt.getUTCDate());
}

const MONTHS = {
  jan:1, january:1,
  feb:2, february:2,
  mar:3, march:3,
  apr:4, april:4,
  may:5,
  jun:6, june:6,
  jul:7, july:7,
  aug:8, august:8,
  sep:9, sept:9, september:9,
  oct:10, october:10,
  nov:11, november:11,
  dec:12, december:12
};

function parseHumanDate(s) {
  s = clean(s);
  if (!s) return { ok:false };

  const low = s.toLowerCase();

  // Relative
  if (low === "today") {
    const p = toMYDatePartsNow();
    return { ok:true, iso: partsToISO(p.y, p.m, p.d) };
  }
  if (low === "yesterday") {
    const p = toMYDatePartsNow();
    const todayIso = partsToISO(p.y, p.m, p.d);
    return { ok:true, iso: addDaysISO(todayIso, -1) };
  }

  // ISO yyyy-mm-dd
  let m = low.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) {
    const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
    if (mo>=1 && mo<=12 && d>=1 && d<=31) return { ok:true, iso: partsToISO(y, mo, d) };
    return { ok:false };
  }

  // Numeric dd-mm-yyyy or dd/mm/yyyy (MY default)
  m = low.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
  if (m) {
    const d = Number(m[1]), mo = Number(m[2]), y = Number(m[3]);
    if (mo>=1 && mo<=12 && d>=1 && d<=31) return { ok:true, iso: partsToISO(y, mo, d) };
    return { ok:false };
  }

  // "12 Jan 2026" / "12 January 2026"
  m = low.match(/^(\d{1,2})\s+([a-z]+)\s+(\d{4})$/);
  if (m) {
    const d = Number(m[1]);
    const monKey = m[2];
    const y = Number(m[3]);
    const mo = MONTHS[monKey];
    if (mo && d>=1 && d<=31) return { ok:true, iso: partsToISO(y, mo, d) };
    return { ok:false };
  }

  return { ok:false };
}

function cmpISO(a, b) {
  // lexical works for YYYY-MM-DD
  if (a === b) return 0;
  return a < b ? -1 : 1;
}

const startRaw = clean($start_raw);
const endRaw = clean($end_raw);

let startNorm = "";
let endNorm = "";
let valid = true;
let err = "";

// Start date required (presence checked later too, but we validate format here if provided)
if (startRaw) {
  const p = parseHumanDate(startRaw);
  if (!p.ok) {
    valid = false;
    err = "START_DATE_INVALID";
  } else {
    startNorm = p.iso;
  }
}

// End date can be OPEN or a date (or empty -> missing)
if (valid && endRaw) {
  if (endRaw.toLowerCase() === "open") {
    endNorm = "OPEN";
  } else {
    const p = parseHumanDate(endRaw);
    if (!p.ok) {
      valid = false;
      err = "END_DATE_INVALID";
    } else {
      endNorm = p.iso;
    }
  }
}

// If both are real dates, enforce end >= start
if (valid && startNorm && endNorm && endNorm !== "OPEN") {
  if (cmpISO(endNorm, startNorm) < 0) {
    valid = false;
    err = "END_BEFORE_START";
  }
}

// If end is missing entirely, mark invalid? (your Checker can also treat as missing)
// Recommended: set invalid ONLY when user provided something but it's wrong.
// Missing end_date should be handled as "missing field" by Checker2.
if (valid) {
  // No extra action
}

return {
  start_date_norm: startNorm || startRaw || "",
  end_date_norm: endNorm || endRaw || "",
  date_valid: valid,
  date_error: err
};

