  const dt = new Date(Date.UTC(y, m - 1, d));
  dt.setUTCDate(dt.getUTCDate() + delta);
  return `${dt.getUTCFullYear()}-${pad2(dt.getUTCMonth() + 1)}-${pad2(dt.getUTCDate())}`;
}

function parseAgoPhraseToDays(v) {
  // Supports:
  // "2 days ago"
  // "1 week 1 day ago"
  // "1 week and 3 days ago"
  // Adds basic "month" support as 30 days/month (configurable)
  const s = v
    .toLowerCase()
    .trim()
    .replace(/,/g, " ")
    .replace(/\s+and\s+/g, " ")
    .replace(/\s+/g, " ");

  if (!s.endsWith("ago")) return null;

  const mo = s.match(/(\d+)\s*month/);
  const wk = s.match(/(\d+)\s*week/);
  const dy = s.match(/(\d+)\s*day/);

  const months = mo ? Number(mo[1]) : 0;
  const weeks  = wk ? Number(wk[1]) : 0;
  const days   = dy ? Number(dy[1]) : 0;

  if (!mo && !wk && !dy) return null;

  // Month assumption: 30 days per month (simple deterministic)
  const total = months * 30 + weeks * 7 + days;
  if (!Number.isFinite(total) || total <= 0) return null;

  return total;
}

function normalizeDate(value) {
  if (value == null) return { ok: false, reason: "EMPTY" };

  const raw = String(value).trim();
  if (!raw) return { ok: false, reason: "EMPTY" };

  const v = raw.toLowerCase();
  const today = todayMY();

  if (v === "open") return { ok: true, iso: "OPEN" };
  if (v === "today") return { ok: true, iso: today };
  if (v === "yesterday") return { ok: true, iso: addDays(today, -1) };

  // yyyy-mm-dd
  let m = v.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return { ok: true, iso: `${m[1]}-${m[2]}-${m[3]}` };

  // dd-mm-yyyy or dd/mm/yyyy (MY)
  m = v.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
  if (m) return { ok: true, iso: `${m[3]}-${pad2(m[2])}-${pad2(m[1])}` };

  // "X month Y week Z day ago" etc (months=30 days)
  const totalDays = parseAgoPhraseToDays(v);
  if (totalDays != null) {
    return { ok: true, iso: addDays(today, -totalDays) };
  }

  return { ok: false, reason: "UNSUPPORTED" };
}

// ---------- main ----------
const input = normalizeToArray($draft3_changes_raw);

let valid = true;
const errors = [];

const normalized = input.map((c, idx) => {
  const field = c?.field;
  if (field === "start_date" || field === "end_date") {
    const r = normalizeDate(c.value);
    if (!r.ok) {
      valid = false;
      errors.push(`CHANGE_${idx}_${field}_${r.reason}`);
      return c; // keep original
    }
    return { ...c, value: r.iso };
  }
  return c;
});

return {
  draft3_changes: normalized,
  draft3_date_valid: valid,
  draft3_date_error: errors.join("|")
};
